# ---------- shared page shell ----------

def css_from(tpl):
    return re.search(r"<style>.*?</style>", tpl, re.S).group(0)


def footer_links(pages):
    links = [("/about/", "About")]
    if "contact" in pages:
        links.append(("/contact/", "Contact"))
    links += [("/privacy/", "Privacy"), ("/feed.xml", "RSS")]
    return "&ensp;".join(f'<a href="{u}">{t}</a>' for u, t in links)


DISCLOSURE = "Partner. OTR News may earn a commission if you sign up, at no cost to you."


def partners_for(topic):
    return [p for p in PARTNERS if p.get("url") and topic in p.get("topics", [])]


def pick_partner(topic, seed=""):
    """Pick one matching partner, rotating fairly between matches."""
    matches = partners_for(topic) or [p for p in PARTNERS if p.get("url")]
    if not matches:
        return None
    n = sum(ord(c) for c in (seed + topic + datetime.now(timezone.utc).strftime("%Y%m%d%H")))
    return matches[n % len(matches)]


def partner_img(p, kind, cls):
    src = p.get(kind)
    if not src:
        return ""
    w, h = p.get(kind + "_w"), p.get(kind + "_h")
    size = f' width="{w}" height="{h}"' if w and h else ""
    return (f'<a class="{cls}" href="{esc(p["url"])}" target="_blank" rel="sponsored noopener">'
            f'<img src="{esc(src)}" alt="{esc(p.get(kind + "_alt", p["name"]))}"{size} loading="lazy" '
            f'onerror="this.parentNode.remove()"></a>')


def partner_box(p):
    if not p:
        return ""
    banner = partner_img(p, "banner", "banner")
    logo = "" if banner else partner_img(p, "logo", "logo")
    return f"""<aside class="partner">
<p class="kicker">{DISCLOSURE}</p>
{banner}
<div class="partner-row">{logo}<div>
<h2>{esc(p['name'])}</h2>
<p>{esc(p['blurb'])}</p>
<a class="btn btn-alt" href="{esc(p['url'])}" target="_blank" rel="sponsored noopener">{esc(p.get('cta', 'Learn more'))}</a>
</div></div>
</aside>"""


def toolkit_body():
    cards = []
    for p in PARTNERS:
        if not p.get("url"):
            continue
        extra = "".join(f' <a class="more-link" href="{esc(u)}" target="_blank" rel="sponsored noopener">{esc(t)}</a>' for t, u in p.get("extra", []))
        img = partner_img(p, "banner", "banner") or partner_img(p, "logo", "logo")
        cards.append(f"""<section class="tool-card">
{img}
<h2>{esc(p['name'])}</h2>
<p>{esc(p['blurb'])}</p>
<a class="btn btn-alt" href="{esc(p['url'])}" target="_blank" rel="sponsored noopener">{esc(p.get('cta', 'Learn more'))}</a>{extra}
</section>""")
    return (f"""<h1>Driver toolkit</h1>
<p class="deck">Services we recommend for owner-operators and small fleets, plus our own free tools.</p>
<p class="fine">Some links on this page are partner links. OTR News may earn a commission if you sign up, at no cost to you. Partners never pay for news coverage, and our reporting is written independently.</p>
<section class="tool-card"><h2>Cost per mile calculator</h2><p>Free. Find your break-even rate before you take the load.</p>
<a class="btn" href="/tools/cost-per-mile/">Open the calculator</a></section>
""" + "".join(cards) + training_box())


def training_box(link=True):
    if not TRAINING_URL:
        return ""
    reg = " from a registered FMCSA training provider" if TRAINING_REGISTERED else ""
    price = f" {esc(TRAINING_PRICE)}." if TRAINING_PRICE else ""
    return f"""<aside class="cta">
<p class="kicker">From {esc(PARENT_BRAND)}</p>
<h2>Getting your CDL?</h2>
<p>Complete your required ELDT theory training online{reg}, at your own pace, right from your phone.{price}</p>
<a class="btn" href="{esc(TRAINING_URL)}" target="_blank" rel="noopener">Start your course</a>
{'<a class="more-link" href="/training/">What is ELDT?</a>' if link else ''}
</aside>"""


def parent_line():
    return f'<p>{SITE_NAME} is a <a href="{esc(TRAINING_URL)}" target="_blank" rel="noopener">{esc(PARENT_BRAND)}</a> company.</p>' if PARENT_BRAND else ""


TRAINING_MD = """
Getting a commercial driver's license starts with **Entry-Level Driver Training (ELDT)**. Since February 7, 2022, federal rules require it before you can take the CDL skills test for the first time.

## Who needs ELDT?

- Anyone getting a **Class A or Class B CDL** for the first time
- Drivers **upgrading** from a Class B to a Class A
- Drivers getting a **school bus (S), passenger (P), or hazardous materials (H)** endorsement for the first time

## What does it involve?

ELDT has two parts:

- **Theory (classroom) training**, which covers the knowledge you need, like vehicle inspections, basic control, hours of service, and handling emergencies. It can be completed online, and you need a score of at least 80% on the final assessment.
- **Behind-the-wheel training**, done in a real truck on a range and on public roads with a qualified instructor.

Both must come from a provider listed on FMCSA's **Training Provider Registry**. When you finish, the provider reports your completion to the Registry, and your state can then let you take the skills test.

## Tips before you start

- **Check the Registry.** Look up any school or online course at tpr.fmcsa.dot.gov before you pay.
- **Get your CLP first**, if your state requires it before training.
- **Ask about employer programs.** Some carriers and city or county employers cover training costs for new drivers.

## Start your theory training

""" 

